# This file was generated by AI

import csv
import importlib.metadata
import json
import sys
from dataclasses import asdict, is_dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

from bees_algorithm.configs import TSP_OPTIMA
from bees_algorithm.utils.validators import (
    validate_continuous_vector,
    validate_tsp_tour,
)
from logger import get_logger

logger = get_logger(__name__)

DEFAULT_RESULTS_DIR = Path("bees_algorithm/results")

PART_A_FIELDS = [
    "instance",
    "cities",
    "optimum",
    "neighbourhood",
    "run_idx",
    "seed",
    "evaluations",
    "initial_best",
    "final_best",
    "gap_pct",
    "runtime_sec",
    "is_valid",
    "validation_errors",
    "solution",
]

PART_B_FIELDS = [
    "function",
    "dimension",
    "lower",
    "upper",
    "global_minimum",
    "run_idx",
    "seed",
    "evaluations",
    "initial_best",
    "final_best",
    "runtime_sec",
    "is_valid",
    "validation_errors",
    "solution",
]


def _serialize_config(cfg: Any) -> dict[str, Any]:
    if cfg is None:
        return {}
    if is_dataclass(cfg):
        return (
            asdict(cfg)
            if not isinstance(cfg, type)
            else {k: v.default for k, v in cfg.__dataclass_fields__.items()}
        )
    return {
        k: getattr(cfg, k)
        for k in dir(cfg)
        if not k.startswith("_") and not callable(getattr(cfg, k))
    }


def _package_version(pkg: str) -> str:
    try:
        return importlib.metadata.version(pkg)
    except importlib.metadata.PackageNotFoundError:
        return "not-installed"


class ExperimentWriter:
    """
    Writes raw per-run metrics, final solutions, convergence histories, and
    experiment metadata into an organized directory structure for both
    Part A (TSP) and Part B (Continuous Function Optimisation).
    """

    def __init__(self, results_dir: str | Path = DEFAULT_RESULTS_DIR):
        self.results_dir = Path(results_dir)
        self.part_a_dir = self.results_dir / "part_a_tsp"
        self.part_b_dir = self.results_dir / "part_b_continuous"

        self._tsp_solutions: dict[str, Any] = {}
        self._continuous_solutions: dict[str, Any] = {}
        self._tsp_histories: dict[tuple[str, str], list[tuple[int, list[float]]]] = {}
        self._continuous_histories: dict[
            tuple[str, int], list[tuple[int, list[float]]]
        ] = {}

        self._ensure_directories()

    def _ensure_directories(self) -> None:
        for base in (self.part_a_dir, self.part_b_dir):
            for sub in ("raw", "histories", "tables", "figures"):
                (base / sub).mkdir(parents=True, exist_ok=True)

    def reset_part_a(self) -> None:
        runs_csv = self.part_a_dir / "raw" / "runs.csv"
        with runs_csv.open("w", newline="", encoding="utf-8") as f:
            csv.DictWriter(f, fieldnames=PART_A_FIELDS).writeheader()
        self._tsp_solutions = {}
        self._tsp_histories = {}
        (self.part_a_dir / "raw" / "solutions.json").write_text(
            "{}\n", encoding="utf-8"
        )

    def reset_part_b(self) -> None:
        runs_csv = self.part_b_dir / "raw" / "runs.csv"
        with runs_csv.open("w", newline="", encoding="utf-8") as f:
            csv.DictWriter(f, fieldnames=PART_B_FIELDS).writeheader()
        self._continuous_solutions = {}
        self._continuous_histories = {}
        (self.part_b_dir / "raw" / "solutions.json").write_text(
            "{}\n", encoding="utf-8"
        )

    def write_metadata(
        self,
        tsp_config: Any = None,
        function_config: Any = None,
        seeds: list[int] | None = None,
    ) -> Path:
        metadata = {
            "generated_at_utc": datetime.now(timezone.utc).isoformat(),
            "python_version": sys.version.split()[0],
            "packages": {
                "numpy": _package_version("numpy"),
                "matplotlib": _package_version("matplotlib"),
                "pytest": _package_version("pytest"),
            },
            "seeds": seeds or [],
            "tsp_config": _serialize_config(tsp_config),
            "function_config": _serialize_config(function_config),
            "tsp_optima": TSP_OPTIMA,
        }
        meta_path = self.results_dir / "metadata.json"
        meta_path.write_text(json.dumps(metadata, indent=2) + "\n", encoding="utf-8")
        return meta_path

    def record_tsp_run(
        self,
        instance: str,
        cities: int,
        optimum: int | float,
        neighbourhood: str,
        run_idx: int,
        seed: int,
        tracker: Any,
        runtime_sec: float,
        problem: Any = None,
    ) -> dict[str, Any]:
        runs_csv = self.part_a_dir / "raw" / "runs.csv"
        if not runs_csv.exists():
            self.reset_part_a()

        solution = (
            list(tracker.best_solution.site)
            if tracker.best_solution.site is not None
            else None
        )
        final_best = float(tracker.best_solution.fitness)
        initial_best = (
            float(tracker.initial_best.fitness)
            if tracker.initial_best is not None
            else float("nan")
        )
        gap_pct = 100.0 * (final_best - optimum) / optimum

        is_valid = True
        errors: list[str] = []
        if problem is not None:
            is_valid, errors = validate_tsp_tour(
                route=solution,
                city_coordinates=problem.city_coordinates,
                distance_matrix=problem.distance_matrix,
                reported_length=final_best,
            )
        if not is_valid:
            logger.warning(
                f"Invalid TSP solution for {instance} ({neighbourhood}, seed={seed}): {errors}"
            )

        row = {
            "instance": instance,
            "cities": cities,
            "optimum": optimum,
            "neighbourhood": neighbourhood,
            "run_idx": run_idx,
            "seed": seed,
            "evaluations": int(tracker.evaluations),
            "initial_best": initial_best,
            "final_best": final_best,
            "gap_pct": gap_pct,
            "runtime_sec": runtime_sec,
            "is_valid": is_valid,
            "validation_errors": "; ".join(errors),
            "solution": json.dumps(solution),
        }

        with runs_csv.open("a", newline="", encoding="utf-8") as f:
            csv.DictWriter(f, fieldnames=PART_A_FIELDS).writerow(row)

        sol_key = f"{instance}__{neighbourhood}__seed_{seed}"
        self._tsp_solutions[sol_key] = {
            "instance": instance,
            "cities": cities,
            "optimum": optimum,
            "neighbourhood": neighbourhood,
            "run_idx": run_idx,
            "seed": seed,
            "evaluations": int(tracker.evaluations),
            "initial_best": initial_best,
            "final_best": final_best,
            "gap_pct": gap_pct,
            "runtime_sec": runtime_sec,
            "is_valid": is_valid,
            "validation_errors": errors,
            "solution": solution,
        }
        (self.part_a_dir / "raw" / "solutions.json").write_text(
            json.dumps(self._tsp_solutions, indent=2) + "\n", encoding="utf-8"
        )

        self._tsp_histories.setdefault((instance, neighbourhood), []).append(
            (seed, list(tracker.history))
        )
        return row

    def flush_tsp_history(self, instance: str, neighbourhood: str) -> Path | None:
        key = (instance, neighbourhood)
        seed_histories = self._tsp_histories.pop(key, None)
        if not seed_histories:
            return None
        out_path = self.part_a_dir / "histories" / f"{instance}_{neighbourhood}.csv"
        self._write_history_csv(out_path, seed_histories)
        return out_path

    def record_continuous_run(
        self,
        function_name: str,
        dimension: int,
        lower: float,
        upper: float,
        global_minimum: float,
        run_idx: int,
        seed: int,
        tracker: Any,
        runtime_sec: float,
        problem: Any = None,
    ) -> dict[str, Any]:
        runs_csv = self.part_b_dir / "raw" / "runs.csv"
        if not runs_csv.exists():
            self.reset_part_b()

        solution = (
            [float(x) for x in tracker.best_solution.site]
            if tracker.best_solution.site is not None
            else None
        )
        final_best = float(tracker.best_solution.fitness)
        initial_best = (
            float(tracker.initial_best.fitness)
            if tracker.initial_best is not None
            else float("nan")
        )

        func = problem.function if problem is not None else None
        is_valid, errors = validate_continuous_vector(
            vector=solution,
            dimension=dimension,
            lower=lower,
            upper=upper,
            func=func,
            reported_value=final_best,
        )
        if not is_valid:
            logger.warning(
                f"Invalid Continuous solution for {function_name} (D={dimension}, seed={seed}): {errors}"
            )

        row = {
            "function": function_name,
            "dimension": dimension,
            "lower": lower,
            "upper": upper,
            "global_minimum": global_minimum,
            "run_idx": run_idx,
            "seed": seed,
            "evaluations": int(tracker.evaluations),
            "initial_best": initial_best,
            "final_best": final_best,
            "runtime_sec": runtime_sec,
            "is_valid": is_valid,
            "validation_errors": "; ".join(errors),
            "solution": json.dumps(solution),
        }

        with runs_csv.open("a", newline="", encoding="utf-8") as f:
            csv.DictWriter(f, fieldnames=PART_B_FIELDS).writerow(row)

        sol_key = f"{function_name}__D{dimension}__seed_{seed}"
        self._continuous_solutions[sol_key] = {
            "function": function_name,
            "dimension": dimension,
            "lower": lower,
            "upper": upper,
            "global_minimum": global_minimum,
            "run_idx": run_idx,
            "seed": seed,
            "evaluations": int(tracker.evaluations),
            "initial_best": initial_best,
            "final_best": final_best,
            "runtime_sec": runtime_sec,
            "is_valid": is_valid,
            "validation_errors": errors,
            "solution": solution,
        }
        (self.part_b_dir / "raw" / "solutions.json").write_text(
            json.dumps(self._continuous_solutions, indent=2) + "\n", encoding="utf-8"
        )

        self._continuous_histories.setdefault((function_name, dimension), []).append(
            (seed, list(tracker.history))
        )
        return row

    def flush_continuous_history(
        self, function_name: str, dimension: int
    ) -> Path | None:
        key = (function_name, dimension)
        seed_histories = self._continuous_histories.pop(key, None)
        if not seed_histories:
            return None
        out_path = self.part_b_dir / "histories" / f"{function_name}_D{dimension}.csv"
        self._write_history_csv(out_path, seed_histories)
        return out_path

    @staticmethod
    def _write_history_csv(
        out_path: Path, seed_histories: list[tuple[int, list[float]]]
    ) -> None:
        header = ["evaluation"] + [f"seed_{seed}" for seed, _ in seed_histories]
        max_len = max((len(hist) for _, hist in seed_histories), default=0)

        with out_path.open("w", newline="", encoding="utf-8") as f:
            writer = csv.writer(f)
            writer.writerow(header)
            for idx in range(max_len):
                row: list[Any] = [idx + 1]
                for _, hist in seed_histories:
                    row.append(hist[idx] if idx < len(hist) else "")
                writer.writerow(row)
